package dev.halloween;
import java.util.*;
import net.fabricmc.fabric.api.event.lifecycle.v1.ServerTickEvents;
import net.minecraft.block.*;
import net.minecraft.entity.*;
import net.minecraft.item.*;
import net.minecraft.server.network.*;
import net.minecraft.storage.*;
import net.minecraft.util.*;
import net.minecraft.util.math.*;

/** Integration: ammunition, loading lock, actual projectile travel/impact, towing and persisted state. */
final class CannonChecks {
 static int stage,age;static ServerPlayerEntity gunner;static FieldCannonEntity gun;static NavalCannonballEntity shot;static RailVehicleEntity ship;static Vec3d origin;static final List<BlockPos> wall=new ArrayList<>();
 static void require(boolean v,String why){if(!v)throw new AssertionError(why);}
 static void register(){if(!Boolean.getBoolean("halloween.cannonTest"))return;ServerTickEvents.END_SERVER_TICK.register(server->{if(stage<0||server.getTicks()<50)return;var w=server.getOverworld();try{age++;
  if(stage==0){server.getTickManager().setTickRate(1000);var cp=new ChunkPos(-66,68);for(int x=-4;x<=4;x++)for(int z=-4;z<=4;z++)w.setChunkForced(cp.x+x,cp.z+z,true);if(age<80)return;
   origin=new Vec3d(-1048.5,101,1088.5);for(var old:w.getOtherEntities(null,new Box(origin.add(-100,-50,-100),origin.add(100,40,100)),e->e instanceof RailVehicleEntity||e instanceof FieldCannonEntity||e instanceof NavalCannonballEntity))old.discard();for(int x=-8;x<=8;x++)for(int z=-10;z<=35;z++)w.setBlockState(BlockPos.ofFloored(origin.add(x,-1,z)),Blocks.STONE.getDefaultState(),Block.NOTIFY_LISTENERS);
   gun=NavalCannons.FIELD_ENTITY.create(w,SpawnReason.EVENT);require(gun!=null,"field carriage created");gun.setPosition(origin);w.spawnEntity(gun);
   gunner=new ServerPlayerEntity(server,w,new com.mojang.authlib.GameProfile(UUID.randomUUID(),"GunnerTest"),net.minecraft.network.packet.c2s.common.SyncedClientOptions.createDefault());gunner.networkHandler=new ServerPlayNetworkHandler(server,new net.minecraft.network.ClientConnection(net.minecraft.network.NetworkSide.SERVERBOUND),gunner,ConnectedClientData.createDefault(gunner.getGameProfile(),false));gunner.setPosition(origin.add(0,0,-2));w.onPlayerConnected(gunner);gunner.getInventory().setStack(1,new ItemStack(NavalCannons.BALL,3));gunner.getInventory().setStack(2,new ItemStack(Items.GUNPOWDER,3));
   gun.interact(gunner,Hand.MAIN_HAND);require(gun.loaded&&gunner.getInventory().getStack(1).getCount()==2&&gunner.getInventory().getStack(2).getCount()==2,"exactly one ball and powder consumed");gun.interact(gunner,Hand.MAIN_HAND);require(gun.loaded&&w.getEntitiesByClass(NavalCannonballEntity.class,gun.getBoundingBox().expand(5),e->true).isEmpty(),"cannot fire during three second preparation");
   var write=NbtWriteView.create(ErrorReporter.EMPTY,w.getRegistryManager());gun.writeData(write);var copy=NavalCannons.FIELD_ENTITY.create(w,SpawnReason.LOAD);copy.readData(NbtReadView.create(ErrorReporter.EMPTY,w.getRegistryManager(),write.getNbt()));require(copy.loaded&&copy.ready==gun.ready,"loaded gun and ready time survive serialization");copy.discard();stage=1;age=0;log("PASS ammunition, reload lock and field gun persistence");
  }else if(stage==1&&age>65){for(int x=-5;x<=5;x++)for(int y=-3;y<=8;y++){var p=BlockPos.ofFloored(origin.add(x,y,26));wall.add(p);w.setBlockState(p,Blocks.OAK_PLANKS.getDefaultState(),Block.NOTIFY_LISTENERS);}gun.interact(gunner,Hand.MAIN_HAND);shot=w.getEntitiesByClass(NavalCannonballEntity.class,gun.getBoundingBox().expand(4),e->true).stream().findFirst().orElseThrow();require(!gun.loaded&&shot.getVelocity().length()>2,"visible cannonball fired with real velocity");stage=2;age=0;
  }else if(stage==2&&age>45){require(shot.isRemoved(),"projectile impacted the obstacle");require(wall.stream().anyMatch(p->w.getBlockState(p).isAir()),"cannonball damaged real wooden wall");gunner.setPosition(origin.add(0,0,2));gunner.setYaw(0);gun.towing=gunner.getUuid();stage=3;age=0;log("PASS actual ballistic flight, collision and blast damage");
  }else if(stage==3){gunner.setPosition(gunner.getEntityPos().add(0,0,.08));if(age>30){require(gun.getZ()>origin.z+1,"field cannon rolls after player rather than teleporting");require(gun.getY()>=origin.y-.05,"wheels remain above solid terrain");gun.towing=null;
    // Both ship inventory and individually loaded broadside guns must survive save/reload.
    ship=NavalContent.spawn(w,3,new Vec3d(-1010,63,1088),0);require(ship!=null,"cutter launched in normal ocean");ship.naval().barrels[0].setStack(0,new ItemStack(Items.EMERALD,11));ship.naval().barrels[7].setStack(0,new ItemStack(Items.DIAMOND,3));ship.naval().cargo.setStack(0,new ItemStack(Items.IRON_INGOT,23));ship.naval().gunLoaded[1]=true;ship.naval().gunReady[1]=w.getTime()+40;
    var write=NbtWriteView.create(ErrorReporter.EMPTY,w.getRegistryManager());ship.writeData(write);var copy=NavalContent.CUTTER_ENTITY.create(w,SpawnReason.LOAD);copy.readData(NbtReadView.create(ErrorReporter.EMPTY,w.getRegistryManager(),write.getNbt()));require(copy.naval().barrels[0].getStack(0).getCount()==11&&copy.naval().barrels[7].getStack(0).getCount()==3&&copy.kind()==3&&copy.naval().cargo.size()==27&&copy.naval().cargo.getStack(0).getCount()==23&&copy.naval().gunLoaded[1],"ship cargo and gun load survive actual entity serialization");copy.discard();
    gunner.setPosition(RailGeometry.rotate(NavalCannons.position(3,1),ship.getYaw()).add(ship.getEntityPos()).add(-1,0,0));NavalCannons.use(ship,gunner,0);require(ship.naval().gunLoaded[0],"broadside gun takes ammunition");stage=4;age=0;log("PASS wheeled towing, ground contact, ship inventory and broadside persistence");}
  }else if(stage==4&&age>65){var ball=NavalCannons.fire(ship,gunner,0);require(ball!=null&&ball.sourceShip.equals(ship.getUuid())&&!ship.naval().gunLoaded[0],"broadside shot records source ship and consumes load");require(ball.getVelocity().x< -2,"port gun fires away from crew");stage=5;age=0;
  }else if(stage==5&&age>30){require(!ship.isRemoved(),"own broadside shot did not hit firing ship");var target=NavalContent.spawn(w,3,ship.getEntityPos().add(0,0,40),0);require(target!=null,"target ship fits ocean");target.hullHealth(110);shot=NavalCannons.BALL_ENTITY.create(w,SpawnReason.EVENT);shot.sourceShip=ship.getUuid();shot.setOwner(gunner);shot.setPosition(target.getEntityPos().add(-12,3.5,0));shot.setVelocity(2.4,0,0);w.spawnEntity(shot);ship=target;stage=6;age=0;log("PASS own ship exclusion; testing solid target hull");}
  else if(stage==6&&age>15){require(shot.isRemoved()&&ship.hullHealth()<110,"cannonball strikes actual target ship geometry and damages hull");
    for(var direction:Direction.Type.HORIZONTAL){var site=new NavalWorks.Site(new BlockPos(-1100,63,1088),direction);var transformed=RailGeometry.rotate(new Vec3d(0,0,10),site.yaw());require(transformed.distanceTo(new Vec3d(direction.getOffsetX()*10,0,direction.getOffsetZ()*10))<.001,"port world orientation matches ship yaw");var side=RailGeometry.rotate(new Vec3d(10,0,0),site.yaw());require(side.distanceTo(Vec3d.of(site.at(10,0,0).subtract(site.base())))<.001,"port lateral basis matches hull");}
    var yard=new NavalWorks.Site(new BlockPos(-1100,63,1100),Direction.SOUTH);var input=new net.minecraft.inventory.SimpleInventory(12);require(NavalWorks.produce(w,yard,input,3)==null,"no free ships from empty yard");RailWorks.add(input,Items.SPRUCE_LOG,128);RailWorks.add(input,Items.WHITE_WOOL,32);RailWorks.add(input,Items.IRON_INGOT,12);var obstruction=yard.at(9,1,18);w.setBlockState(obstruction,Blocks.AIR.getDefaultState(),Block.NOTIFY_LISTENERS);var previous=w.getBlockState(obstruction);w.setBlockState(obstruction,Blocks.STONE.getDefaultState(),Block.NOTIFY_LISTENERS);require(NavalWorks.produce(w,yard,input,3)==null&&input.count(Items.SPRUCE_LOG)==128,"blocked berth retains all materials");w.setBlockState(obstruction,previous,Block.NOTIFY_LISTENERS);var vessel=NavalWorks.produce(w,yard,input,3);require(vessel!=null&&input.isEmpty()&&vessel.anchored(),"real cutter launched only after exact timber, cloth and iron consumed: vessel="+vessel+" timber="+input.count(Items.SPRUCE_LOG)+" water="+w.getBlockState(yard.at(9,-3,18))+" around="+w.getOtherEntities(null,new Box(yard.at(9,0,18)).expand(20),e->e instanceof RailVehicleEntity).stream().map(e->e.getEntityPos().toString()).toList());require(VillageEconomy.factoryRecipe("weaponsmith",8).product()==NavalCannons.BALL&&VillageEconomy.factoryRecipe("weaponsmith",12).product()==NavalCannons.FIELD_GUN,"third era factory produces shot and field guns");log("PASS port orientation, resource manufacturing, blocked berth rollback and third era artillery recipes");
    var manifest=new ItemStack(Items.EMERALD,13);
    manifest.set(net.minecraft.component.DataComponentTypes.CUSTOM_NAME,net.minecraft.text.Text.literal(UUID.randomUUID().toString()));
    ship.naval().cargo.setStack(0,manifest);
    var wreckArea=ship.getBoundingBox().expand(3);
    var lethal=w.getDamageSources().generic();
    require(ship.damage(w,lethal,ship.hullHealth()+1)&&ship.isRemoved(),"lethal hit destroys the ship");
    require(!ship.damage(w,lethal,100),"removed hull ignores subsequent damage");
    var cargoDrops=w.getEntitiesByClass(net.minecraft.entity.ItemEntity.class,wreckArea,item->ItemStack.areItemsAndComponentsEqual(item.getStack(),manifest));
    require(cargoDrops.stream().mapToInt(item->item.getStack().getCount()).sum()==13,"sinking ship drops cargo exactly once");
    log("PASS lethal hull hit and single cargo drop");
    w.removePlayer(gunner,Entity.RemovalReason.DISCARDED);stage=-1;log("PASS naval cannon fire, target hull damage and yard production; integration suite complete");server.stop(false);}
 }catch(Throwable e){stage=-1;org.slf4j.LoggerFactory.getLogger("cannon-test").error("FAIL stage="+stage,e);server.stop(false);}});}
 static void log(String s){org.slf4j.LoggerFactory.getLogger("cannon-test").info(s);}
}
